item.command:
/bin/bash -lc "sed -n '1,240p' inputs_manifest.json
for z in inputs/scogs_animals.zip inputs/scogs_fungi.zip; do
  echo \""'$z"
  unzip -Z1 "$z" | awk '"'
    /\\.treefile"'$/ {tree++}
    /'"\\.mldist"'$/ {ml++}
    /'"\\.bionj"'$/ {bj++}
    /'"\\.iqtree"'$/ {iq++}
    /'"\\.mafft\\.clipkit"'$/ {aln++}
    /'"\\.faa"'$/ {faa++}
    END {print "treefile="tree, "mldist="ml, "bionj="bj, "iqtree="iq, "clipkit="aln, "faa="faa}'"'
done"

